// Define Node interface here
interface Node {
  id: string;
  label: string;
}

// Define Edge interface here
interface Edge {
  source: string;
  target: string;
  label: string;
}

// Define WorkflowGraph type here
type WorkflowGraph = {
  nodes: Node[];
  edges: Edge[];
};

// Create sample workflow data here
const sampleWorkflow: WorkflowGraph = {
  nodes: [
    { id: 'start', label: 'Start' },
    { id: 'process', label: 'Process' },
    { id: 'end', label: 'End' }
  ],
  edges: [
    { source: 'start', target: 'process', label: 'to process' },
    { source: 'process', target: 'end', label: 'to end' }
  ]
};

// Create NodeDisplay component here
const NodeDisplay = ({ node }: { node: Node }) => {
  return <div>{node.label}</div>;
};

// Create EdgeDisplay component here
const EdgeDisplay = ({ edge }: { edge: Edge }) => {
  return <div>{edge.label}</div>;
};

// Create WorkflowGraphVisualizer component here
const WorkflowGraphVisualizer = ({ graph }: { graph: WorkflowGraph }) => {
  return (
    <div>
      {graph.nodes.map(node => (
        <NodeDisplay key={node.id} node={node} />
      ))}
      {graph.edges.map(edge => (
        <EdgeDisplay key={`${edge.source}-${edge.target}`} edge={edge} />
      ))}
    </div>
  );
};

// Add your component here that renders the workflow
const WorkflowApp = () => {
  return (
    <div>
      <WorkflowGraphVisualizer />
    </div>
  );
};

export default WorkflowApp;

