// Example: a validation function
function validateWorkflow(graph: WorkflowGraph): boolean {
  // Check that all edge sources and targets exist in nodes
  const nodeIds = graph.nodes.map(node => node.id);
  return graph.edges.every(edge => 
    nodeIds.includes(edge.source) && nodeIds.includes(edge.target)
  );
}

